// CHANGELOG RENDERING
// ═══════════════════════════════════════════════════════════════
function renderChangelog() {
  const badge = document.getElementById('versionBadge');
  if (badge) badge.textContent = QUIZ_VERSION;
  const body = document.getElementById('clBody');
  if (!body) return;
  body.innerHTML = CHANGELOG.map((entry, i) => {
    const items = entry.changes.map(c => `<li>${c}</li>`).join('');
    const divider = i < CHANGELOG.length - 1 ? '<hr class="cl-divider">' : '';
    return `<div class="cl-entry"><div class="cl-header"><span class="cl-ver">${entry.version}</span><span class="cl-date">${entry.date}</span><span class="cl-summary">— ${entry.summary}</span></div><ul class="cl-changes">${items}</ul>${divider}</div>`;
  }).join('');
}
function toggleChangelog() {
  const btn = document.getElementById('clToggle');
  const body = document.getElementById('clBody');
  const isOpen = body.classList.contains('visible');
  body.classList.toggle('visible', !isOpen);
  btn.classList.toggle('open', !isOpen);
}


// ═══════════════════════════════════════════════════════════════
// VERSION NAG — checks remote JSON for newer version
// ═══════════════════════════════════════════════════════════════
// ↓↓↓ REPLACE THIS URL after creating your GitHub Gist (see setup instructions) ↓↓↓
  const VERSION_CHECK_URL = "https://gist.githubusercontent.com/KristianS9/e9043cd2ebc9585bc29a4725d7c1949b/raw/quiz_version.json";

function checkForUpdate() {
  // Only run once per session — skip if already checked
  if (sessionStorage.getItem('versionChecked')) return;
  sessionStorage.setItem('versionChecked', '1');

  fetch(VERSION_CHECK_URL + '?t=' + Date.now(), {
    cache: 'no-store',
    signal: AbortSignal.timeout(5000)          // 5s timeout — fail silently
  })
  .then(r => r.json())
  .then(data => {
    // data = { "version": "vX.Y", "message": "optional extra text" }
    if (!data || !data.version) return;
    if (data.version !== QUIZ_VERSION) {
      const nag = document.getElementById('updateNag');
      const msg = document.getElementById('nagMsg');
      if (!nag || !msg) return;
      // Build message
      let text = `Your copy is ${QUIZ_VERSION} — the latest is ${data.version}. Visit https://KristianS9.github.io/Phase1-Quiz/ for the latest version.`;
      if (data.message) text += ' ' + data.message;
      msg.textContent = text;
      nag.classList.add('visible');
    }
  })
  .catch(() => {
    // Network offline, CORS error, timeout — fail silently, no banner
  });
}



