// REPORT QUESTION
// ═══════════════════════════════════════════════════════════════
const REPORT_DS_ID = 'cfdef006-5159-4e62-89a0-08d938bb741e';
if (!state.flagged) state.flagged = {};
let _rQIdx = null, _rSrc = null;

function openReport(qIdx, src) {
  const item = state.questions[qIdx];
  if (!item) return;
  _rQIdx = qIdx; _rSrc = src;
  document.getElementById('rdQuestion').textContent = item.q[0];
  // Re-render body fully
  document.getElementById('rdBody').innerHTML = `
    <span class="rd-label">What is the issue?</span>
    <div class="report-reasons">
      <label class="reason-opt"><input type="radio" name="rdR" value="Incorrect answer"> Incorrect answer</label>
      <label class="reason-opt"><input type="radio" name="rdR" value="Misleading or ambiguous wording"> Misleading or ambiguous wording</label>
      <label class="reason-opt"><input type="radio" name="rdR" value="Outdated information"> Outdated information</label>
      <label class="reason-opt"><input type="radio" name="rdR" value="Poor distractor quality"> Poor distractor quality</label>
      <label class="reason-opt"><input type="radio" name="rdR" value="Other"> Other</label>
    </div>
    <span class="rd-label">Your reasoning <span style="color:var(--bad)">*</span></span>
    <textarea class="report-extra" id="rdExtra" placeholder="e.g. The correct answer should be B because..."></textarea>
    <div class="report-footer">
      <button class="btn" onclick="closeReport()">Cancel</button>
      <button class="btn btn-red" onclick="submitReport()">Submit report</button>
    </div>`;
  document.querySelectorAll('.reason-opt').forEach(opt => {
    opt.addEventListener('click', () => {
      document.querySelectorAll('.reason-opt').forEach(o => o.classList.remove('selected'));
      opt.classList.add('selected');
    });
  });
  document.getElementById('reportOverlay').style.display = 'flex';
}

function closeReport() {
  document.getElementById('reportOverlay').style.display = 'none';
  _rQIdx = null; _rSrc = null;
}

async function submitReport() {
  const rEl = document.querySelector('input[name="rdR"]:checked');
  if (!rEl) {
    document.querySelectorAll('.reason-opt').forEach(o => o.style.outline = '1px solid rgba(255,107,122,0.6)');
    return;
  }
  const extra = (document.getElementById('rdExtra') || {}).value || '';
  if (!extra.trim()) {
    document.getElementById('rdExtra').style.borderColor = 'rgba(255,107,122,0.6)';
    return;
  }
  const reason = rEl.value + ' — ' + extra.trim();
  const item = state.questions[_rQIdx];
  if (!item) { closeReport(); return; }

  document.getElementById('rdBody').innerHTML = '<div class="report-msg" style="color:var(--ink-dim)">Submitting…</div>';

  try {
    const resp = await fetch('https://fidus.kristian-s.workers.dev/api/report', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        question: item.q[0],
        options:  item.q[1],
        correct:  item.q[2],
        source:   _rSrc || '',
        lecture:  item.lecture   || '',
        block:    item.blockName || '',
        qIdx:     _rQIdx,
        reason:   reason.substring(0, 500),
        email:    localStorage.getItem('quiz_email_verified') || '',
      }),
    });
    if (!resp.ok) throw new Error('server error');
    // Mark as flagged client-side
    if (!state.flagged) state.flagged = {};
    state.flagged[(state.attemptId||'x') + '_' + _rQIdx] = true;
    document.getElementById('rdBody').innerHTML = '<div class="report-msg" style="color:var(--ok)">&#10003; Reported — thank you</div>';
    setTimeout(() => { closeReport(); renderQ(); }, 1800);
  } catch(e) {
    document.getElementById('rdBody').innerHTML = `<div class="report-msg" style="color:var(--bad)">&#10007; Could not submit — check your connection</div><div class="report-footer" style="margin-top:12px"><button class="btn" onclick="closeReport()">Close</button></div>`;
  }
}

// ═══════════════════════════════════════════════════════════════
// RESUME SYSTEM
// ═══════════════════════════════════════════════════════════════
const RESUME_KEY = 'p1quiz_resume';

// ─── Recency (cooldown) system ────────────────────────────────
const RECENT_KEY = 'p1quiz_recent';
const RECENT_MAX = 300;

function loadRecentQ() { return load(RECENT_KEY, []); }

function addRecentQ(items) {
  const keys = items.map(item => item.blockName + '|' + item.lecture + '|' + item.qIdx);
  let recent = loadRecentQ().concat(keys);
  if (recent.length > RECENT_MAX) recent = recent.slice(recent.length - RECENT_MAX);
  save(RECENT_KEY, recent);
}

function sortPoolByRecency(pool) {
  const recentSet = new Set(loadRecentQ());
  const fresh = [], seen = [];
  pool.forEach(item => {
    (recentSet.has(item.blockName + '|' + item.lecture + '|' + item.qIdx) ? seen : fresh).push(item);
  });
  fisherYates(fresh);
  fisherYates(seen);
  return [...fresh, ...seen];
}

function saveResume() {
  if (!state.questions || !state.questions.length) return; // no active MCQ quiz
  // Serialise the current in-progress attempt
  // questions array contains objects with {lecture, qIdx, blockName, q:[...]}
  // q[1] (options) may have been shuffled — save as-is so resume is identical
  const data = {
    blockId:     state.blockId,
    questions:   state.questions,
    answers:     state.answers,
    currentQ:    state.currentQ,
    attemptId:   state.attemptId,
    isRandom:    state.isRandom,
    isAllRandom: state.isAllRandom,
    qTitle:      document.getElementById('qTitle') ? document.getElementById('qTitle').textContent : '',
    savedAt:     Date.now()
  };
  save(RESUME_KEY, data);
}

function clearResume() {
  try { localStorage.removeItem(RESUME_KEY); } catch(e) {}
}

function loadResume() {
  return load(RESUME_KEY, null);
}

function buildResumeTile() {
  const data = loadResume();
  const tile = document.getElementById('resumeTile');
  if (!tile) return;
  if (!data || !data.questions || !data.questions.length) {
    tile.classList.remove('visible');
    return;
  }
  const answered = Object.keys(data.answers || {}).length;
  const total    = data.questions.length;
  const pct      = Math.round(answered / total * 100);
  const label    = data.qTitle || (data.isAllRandom ? '⚡ All Blocks — Full Random' : 'Attempt');
  const elapsed  = Math.round((Date.now() - data.savedAt) / 60000);
  const timeStr  = elapsed < 2 ? 'just now' : elapsed < 60 ? `${elapsed}m ago` : `${Math.round(elapsed/60)}h ago`;

  document.getElementById('rtLabel').textContent = '▶ Resume: ' + label;
  document.getElementById('rtMeta').textContent  = `${answered} of ${total} answered · exited ${timeStr}`;
  document.getElementById('rtFill').style.width  = pct + '%';
  tile.classList.add('visible');
}

function resumeAttempt() {
  const data = loadResume();
  if (!data) return;
  // Restore state
  state.blockId     = data.blockId;
  state.questions   = data.questions;
  state.answers     = data.answers || {};
  state.currentQ    = data.currentQ || 0;
  state.attemptId   = data.attemptId;
  state.isRandom    = data.isRandom || false;
  state.isAllRandom = data.isAllRandom || false;
  // Restore header title
  const titleEl = document.getElementById('qTitle');
  if (titleEl && data.qTitle) titleEl.textContent = data.qTitle;
  showScreen('quiz');
  renderQ();
}

function dismissResume() {
  clearResume();
  const tile = document.getElementById('resumeTile');
  if (tile) tile.classList.remove('visible');
}

function buildHome() {
  renderChangelog();
  checkForUpdate();
  buildResumeTile();
  const g = document.getElementById('bGrid');
  g.innerHTML = '';
  Object.entries(BLOCKS).forEach(([id, b]) => {
    if (b.hidden) return; // skip blocks with their own dedicated screen (e.g. eq2)
    let totalQ = 0;
    Object.values(b.lectures).forEach(qs => totalQ += qs.length);
    const s = allStats[id] || {};
    let done = 0, correct = 0;
    Object.values(s).forEach(ls => { done += ls.answered; correct += ls.correct; });
    const pct = done ? Math.round(correct/done*100) : null;
    const card = document.createElement('button');
    card.className = 'bcard';
    card.innerHTML = `<div class="bcard-name" style="color:${b.color}">${b.name}</div>
      <div class="bcard-sub">${b.sub}</div>
      <div class="bcard-meta">${totalQ} questions${pct !== null ? ` · ${pct}% best` : ''}</div>`;
    card.onclick = () => openSetup(id);
    g.appendChild(card);
  });
  // High Yield SocPop SAQ tile
  const saqCard = document.createElement('button');
  saqCard.className = 'bcard saq-tile';
  saqCard.innerHTML = `<div class="bcard-name">High Yield SocPop</div><div class="bcard-sub">Short-answer questions · exam format</div><div class="bcard-meta">58 SAQs · Pop &amp; Soc</div>`;
  saqCard.onclick = () => openSaqPicker();
  g.appendChild(saqCard);
}

// ═══════════════════════════════════════════════════════════════
// SETUP MODAL
// ═══════════════════════════════════════════════════════════════
function openSetup(blockId) {
  state.blockId = blockId;
  const b = BLOCKS[blockId];
  document.getElementById('setupTitle').textContent = `Configure — ${b.name}`;
  document.getElementById('modeSelect').value = 'all';
  document.getElementById('randomRow').style.display = 'none';
  const lecGrid = document.getElementById('lecGrid');
  lecGrid.innerHTML = '';
  Object.keys(b.lectures).forEach(lec => {
    const label = document.createElement('label');
    label.className = 'lec-check';
    label.innerHTML = `<input type="checkbox" value="${lec}" checked> ${lec}`;
    lecGrid.appendChild(label);
  });
  document.getElementById('setupModal').style.display = 'flex';
}
function toggleMode() {
  const mode = document.getElementById('modeSelect').value;
  document.getElementById('randomRow').style.display = mode === 'random' ? 'block' : 'none';
}
function setAllLecs(checked) {
  document.querySelectorAll('#lecGrid input[type=checkbox]').forEach(cb => cb.checked = checked);
}
function closeSetup() { document.getElementById('setupModal').style.display = 'none'; }

function fisherYates(arr) {
  for (let i = arr.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [arr[i], arr[j]] = [arr[j], arr[i]];
  }
  return arr;
}

function shuffleAnswers(q) {
  // q is [text, opts, correct, expl]
  // Returns a new q with opts shuffled and correct letter remapped
  const [text, opts, correct, expl] = q;
  const correctIdx = ['A','B','C','D','E'].indexOf(correct);
  // Build indexed opts, shuffle, remap correct
  const indexed = opts.map((o, i) => ({o, isCorrect: i === correctIdx}));
  fisherYates(indexed);
  const newOpts = indexed.map(x => x.o);
  const newCorrectIdx = indexed.findIndex(x => x.isCorrect);
  const newCorrect = ['A','B','C','D','E'][newCorrectIdx];
  return [text, newOpts, newCorrect, expl];
}


// ═══════════════════════════════════════════════════════════════
// ALL QUESTIONS — RANDOM ORDER (dedicated home button)
// ═══════════════════════════════════════════════════════════════
let pendingAllRandomPool = [];
let arSelectedCount = null;

function startAllRandom() {
  // Build pool: every question from every block and lecture
  pendingAllRandomPool = [];
  Object.entries(BLOCKS).forEach(([bid, block]) => {
    if (block.hidden) return; // exclude dedicated blocks (e.g. eq2) from all-random
    Object.entries(block.lectures).forEach(([lec, qs]) => {
      qs.forEach((q, idx) => {
        pendingAllRandomPool.push({ lecture: lec, qIdx: idx, q, blockName: block.name, blockId: bid });
      });
    });
  });
  // Add SAQ questions to the pool
  SAQ_QUESTIONS.forEach((q, idx) => {
    pendingAllRandomPool.push({ type: 'saq', saqIdx: idx, blockName: 'High Yield SocPop', lecture: q.topic });
  });
  fisherYates(pendingAllRandomPool);

  // Reset selection state
  arSelectedCount = null;
  document.getElementById('arStartBtn').disabled = true;
  document.getElementById('arCustom').value = '';

  // Build preset buttons
  const presets = [10, 25, 50, 100, pendingAllRandomPool.length];
  const presetLabels = ['10', '25', '50', '100', 'All (' + pendingAllRandomPool.length + ')'];
  const container = document.getElementById('arPresets');
  container.innerHTML = '';
  presets.forEach((n, i) => {
    const btn = document.createElement('button');
    btn.className = 'ar-preset-btn';
    btn.textContent = presetLabels[i];
    btn.dataset.count = n;
    btn.onclick = () => arSelectCount(n, null, btn);
    container.appendChild(btn);
  });

  document.getElementById('arModal').style.display = 'flex';
}

function arSelectCount(count, customVal, clickedBtn) {
  const n = count !== null ? count : parseInt(customVal);
  if (!n || n < 1) { arSelectedCount = null; document.getElementById('arStartBtn').disabled = true; return; }
  arSelectedCount = Math.min(n, pendingAllRandomPool.length);
  document.getElementById('arStartBtn').disabled = false;
  // Highlight selected preset button
  document.querySelectorAll('.ar-preset-btn').forEach(b => b.classList.remove('on'));
  if (clickedBtn) {
    clickedBtn.classList.add('on');
    document.getElementById('arCustom').value = '';
  } else {
    document.querySelectorAll('.ar-preset-btn').forEach(b => b.classList.remove('on'));
  }
}

function closeArModal() {
  document.getElementById('arModal').style.display = 'none';
}

function confirmAllRandom() {
  if (!arSelectedCount) return;
  closeArModal();

  const pool = sortPoolByRecency(pendingAllRandomPool).slice(0, arSelectedCount).map(item =>
    item.type === 'saq' ? item : { ...item, q: shuffleAnswers(resolveQuestion(item.q)) }
  );

  state.questions    = pool;
  state.answers      = {};
  state.questionTimes = {};
  state.currentQ     = 0;
  state.attemptId    = Date.now().toString();
  state.isRandom     = true;
  state.isAllRandom  = true;
  state.blockId      = 'all';
  clearResume();

  document.getElementById('qTitle').textContent = 'All Blocks — Random Mix (' + arSelectedCount + ' questions)';
  showScreen('quiz');
  renderQ();
}



function startQuiz() {
  const mode = document.getElementById('modeSelect').value;
  const numQ = parseInt(document.getElementById('numQ').value) || 20;
  const b = BLOCKS[state.blockId];
  const selected = Array.from(document.querySelectorAll('#lecGrid input:checked')).map(cb => cb.value);
  if (!selected.length) { alert('Please select at least one lecture.'); return; }
  closeSetup();
  clearResume(); // clear any previous resume when starting fresh

  // Build flat question list
  let pool = [];

  if (mode === 'all-random') {
    // Collect ALL questions from ALL blocks, ALL lectures
    Object.entries(BLOCKS).forEach(([bid, block]) => {
      Object.entries(block.lectures).forEach(([lec, qs]) => {
        qs.forEach((q, idx) => pool.push({lecture: lec, qIdx: idx, q: shuffleAnswers(resolveQuestion(q)), blockName: block.name}));
      });
    });
    pool = sortPoolByRecency(pool);
    state.isRandom = true;
    state.isAllRandom = true;
  } else {
    selected.forEach(lec => {
      b.lectures[lec].forEach((q, idx) => pool.push({lecture: lec, qIdx: idx, q: resolveQuestion(q), blockName: b.name}));
    });
    if (mode === 'random') {
      pool = sortPoolByRecency(pool).slice(0, Math.min(numQ, pool.length));
      pool = pool.map(item => ({ ...item, q: shuffleAnswers(resolveQuestion(item.q)) }));
      state.isRandom = true;
      state.isAllRandom = false;
    } else {
      state.isRandom = false;
      state.isAllRandom = false;
    }
  }

  state.questions = pool;
  state.answers = {};
  state.questionTimes = {};
  state.currentQ = 0;
  state.attemptId = Date.now().toString();

  document.getElementById('qTitle').textContent = mode === 'all-random' ? 'All Blocks — Full Random' : b.name;
  showScreen('quiz');
  renderQ();
}

// ═══════════════════════════════════════════════════════════════
// QUESTION TIMER
// ═══════════════════════════════════════════════════════════════
function _lerpColor(a, b, t) {
  const ah = parseInt(a.slice(1), 16), bh = parseInt(b.slice(1), 16);
  const ar = (ah>>16)&0xff, ag = (ah>>8)&0xff, ab = ah&0xff;
  const br = (bh>>16)&0xff, bg = (bh>>8)&0xff, bb = bh&0xff;
  return `rgb(${Math.round(ar+(br-ar)*t)},${Math.round(ag+(bg-ag)*t)},${Math.round(ab+(bb-ab)*t)})`;
}
function _timerColor(secs) {
  if (secs <= 45) return _lerpColor('#7ef0b4', '#ffc864', secs / 45);
  if (secs <= 60) return _lerpColor('#ffc864', '#ff6b7a', (secs - 45) / 15);
  return '#ff6b7a';
}
function updateTimerEl(secs) {
  const el = document.getElementById('qTimer');
  if (!el) return;
  const m = Math.floor(secs / 60), s = secs % 60;
  el.textContent = `${m}:${String(s).padStart(2, '0')}`;
  el.style.color = _timerColor(secs);
}
function startQTimer() {
  clearInterval(_timerInterval);
  _timerStart = Date.now();
  updateTimerEl(0);
  _timerInterval = setInterval(() => {
    updateTimerEl(Math.floor((Date.now() - _timerStart) / 1000));
  }, 500);
}
function stopQTimer() {
  clearInterval(_timerInterval);
  _timerInterval = null;
  if (_timerStart === null) return 0;
  const elapsed = Math.round((Date.now() - _timerStart) / 1000);
  _timerStart = null;
  return elapsed;
}
function setTimerPref(on) {
  timerEnabled = on;
  localStorage.setItem('p1quiz_timer', on ? '1' : '0');
  ['timerToggleSetup', 'timerToggleAr'].forEach(id => {
    const el = document.getElementById(id);
    if (el) el.checked = on;
  });
}
function syncTimerCheckboxes() {
  ['timerToggleSetup', 'timerToggleAr'].forEach(id => {
    const el = document.getElementById(id);
    if (el) el.checked = timerEnabled;
  });
}

// ═══════════════════════════════════════════════════════════════
// QUIZ
// ═══════════════════════════════════════════════════════════════
function renderQ() {
  const total = state.questions.length;
  const i = state.currentQ;
  if (state.questions[i].type === 'saq') { renderSaqInlineQ(); return; }
  const {lecture, qIdx, q} = state.questions[i];
  const [text, opts, correct, expl] = q;
  const correctIdx = ['A','B','C','D','E'].indexOf(correct);
  const saved = state.answers[i];

  // Timer: stop any running interval, then start fresh or show frozen time
  const timerEl = document.getElementById('qTimer');
  if (timerEl) timerEl.style.display = timerEnabled ? '' : 'none';
  stopQTimer();
  if (timerEnabled) {
    if (saved !== undefined) {
      updateTimerEl(state.questionTimes[i] || 0);
    } else {
      startQTimer();
    }
  }

  // Header / progress
  const answered = Object.keys(state.answers).length;
  document.getElementById('qMeta').textContent = `${lecture}${state.isRandom ? ' · Random mode' : ''}`;
  const pct = (i / total) * 100;
  document.getElementById('pFill').style.width = pct + '%';
  document.getElementById('pLeft').textContent = `${answered} answered`;
  document.getElementById('pRight').textContent = `${i+1} / ${total}`;
  document.getElementById('qCtr').textContent = `Q${i+1} of ${total}`;
  document.getElementById('prevBtn').disabled = i === 0;
  document.getElementById('nextBtn').style.display = i < total - 1 ? '' : 'none';
  document.getElementById('finBtn').style.display = i === total - 1 ? '' : 'none';

  // Options
  const optsHTML = opts.map((o, oi) => {
    let cls = 'opt';
    if (saved !== undefined) {
      if (oi === saved && oi === correctIdx) cls += ' correct';
      else if (oi === saved && oi !== correctIdx) cls += ' wrong';
      else if (oi === correctIdx) cls += ' reveal';
    }
    const dis = saved !== undefined ? 'disabled' : '';
    return `<button class="${cls}" onclick="selectAnswer(${oi})" ${dis}><span class="opt-label">${String.fromCharCode(65+oi)}.</span>${o}</button>`;
  }).join('');

  // Explanation
  let explHTML = '';
  if (saved !== undefined) {
    const isOk = saved === correctIdx;
    const ico = isOk ? '✓ Correct' : `✗ Incorrect — correct answer: ${correct}`;
    const cls = isOk ? 'ok' : 'bad';
    // Determine if this is from Notion notes
    const isNotionNote = [3].includes(parseInt(state.blockId)) && lecture === 'Introduction to Neurophysiology';
    // Parse source tag: Notion | external academic source | medical knowledge
    let tag;
    if (expl.startsWith('From your Notion') || expl.includes('From the CTB')) {
      tag = `<span class="source-tag tag-notion">📖 From your Notion notes</span>`;
    } else {
      // Check for external source URL embedded in explanation: [Source: Label — https://...]
      const srcMatch = expl.match(/\[Source:\s*([^—]+)\s*—\s*(https?:\/\/[^\]]+)\]/);
      if (srcMatch) {
        const srcLabel = srcMatch[1].trim();
        const srcUrl = srcMatch[2].trim();
        tag = `<span class="source-tag tag-web">🔗 <a href="${srcUrl}" target="_blank" rel="noopener" style="color:inherit;text-decoration:underline">${srcLabel}</a></span>`;
      } else {
        tag = `<span class="source-tag tag-web">🌐 Medical knowledge</span>`;
      }
    }

    explHTML = `<div class="expl">
      <button class="expl-toggle ${cls}" onclick="this.nextElementSibling.classList.toggle('hidden')">
        ${ico} <span>▾ Explanation</span>
      </button>
      <div class="expl-body">
        <div class="notion-extract">${expl.replace(/\s*\[Source:[^\]]+\]$/, '')}</div>
        ${tag}
      </div>
    </div>`;
  }

  const _src = (q[3]||'').includes('From your Notion') || (q[3]||'').includes('From the CTB') ? 'From Notion'
             : 'AI-generated';
  const _fKey = (state.attemptId||'x') + '_' + state.currentQ;
  const _flagged = state.flagged && state.flagged[_fKey];
  const _flagBtn = `<button class="flag-btn${_flagged?' flagged':''}" onclick="openReport(${state.currentQ},'${_src.replace(/'/g,"\\'")}')">&#9873; ${_flagged?'Reported':'Report question'}</button>`;

  document.getElementById('qArea').innerHTML = `
    <div class="qcard">
      <div class="lec-tag">${lecture}</div>
      <div class="qtext">${text}</div>
      <div class="opts">${optsHTML}</div>
      ${explHTML}
      ${_flagBtn}
    </div>`;
}

function selectAnswer(i) {
  if (state.answers[state.currentQ] !== undefined) return;
  state.answers[state.currentQ] = i;
  if (timerEnabled) state.questionTimes[state.currentQ] = stopQTimer();
  saveResume(); // persist progress on every answer
  if(typeof shaderAnswerFlash==='function'){
    const cIdx=['A','B','C','D','E'].indexOf(state.questions[state.currentQ].q[2]);
    shaderAnswerFlash(i===cIdx);
  }
  const {lecture, qIdx, q} = state.questions[state.currentQ];
  const correctIdx = ['A','B','C','D','E'].indexOf(q[2]);
  const isCorrect = i === correctIdx;

  // Update rolling stats (skip for all-random — tracked via allAttempts only)
  if (!state.isAllRandom) {
    if (!allStats[state.blockId]) allStats[state.blockId] = {};
    if (!allStats[state.blockId][lecture]) allStats[state.blockId][lecture] = {answered:0, correct:0};
    allStats[state.blockId][lecture].answered++;
    if (isCorrect) allStats[state.blockId][lecture].correct++;
    saveStats();
  }

  renderQ();
}

function nav(dir) {
  const newIdx = state.currentQ + dir;
  if (newIdx < 0 || newIdx >= state.questions.length) return;
  state.currentQ = newIdx;
  renderQ();
}

function correctlyAnsweredItems() {
  return state.questions.filter((item, i) => {
    const chosen = state.answers[i];
    if (chosen === undefined) return false;
    return chosen === ['A','B','C','D','E'].indexOf(item.q[2]);
  });
}

function savePartial() {
  if (!state.questions.length) return; // no active MCQ quiz (e.g. in SAQ mode)
  addRecentQ(correctlyAnsweredItems());
  saveAttemptRecord();
}

function finishAttempt() {
  stopQTimer();
  addRecentQ(correctlyAnsweredItems());
  saveAttemptRecord();
  clearResume(); // attempt done — remove resume tile
  showResults();
}

function saveAttemptRecord() {
  const qs = state.questions;
  const total = qs.length;
  let correct = 0;
  const lecBreakdown = {};
  qs.forEach((item, i) => {
    const chosen = state.answers[i];
    if (chosen === undefined) return;
    let ok;
    if (item.type === 'saq') {
      ok = chosen === 'got';
    } else {
      const correctIdx = ['A','B','C','D','E'].indexOf(item.q[2]);
      ok = chosen === correctIdx;
    }
    if (ok) correct++;
    if (!lecBreakdown[item.lecture]) lecBreakdown[item.lecture] = {answered:0, correct:0, total: qs.filter(q=>q.lecture===item.lecture).length};
    lecBreakdown[item.lecture].answered++;
    if (ok) lecBreakdown[item.lecture].correct++;
  });
  const answered = Object.keys(state.answers).length;
  const timedQs = Object.values(state.questionTimes || {});
  const avgTimeSecs = timedQs.length ? Math.round(timedQs.reduce((a,b) => a+b, 0) / timedQs.length) : null;
  const record = {
    id: state.attemptId,
    blockId: state.blockId,
    blockName: state.blockId === 'all' ? 'All Blocks' : (BLOCKS[state.blockId] ? BLOCKS[state.blockId].name : state.blockId),
    date: new Date().toISOString(),
    total, answered, correct,
    pct: answered ? Math.round(correct/answered*100) : 0,
    isRandom: state.isRandom,
    breakdown: lecBreakdown,
    avgTimeSecs
  };
  // Update existing record if already saved (e.g. via savePartial on exit), or add new
  const existingIdx = allAttempts.findIndex(a => a.id === state.attemptId);
  if (existingIdx >= 0) {
    allAttempts[existingIdx] = record;
  } else {
    allAttempts.push(record);
  }
  saveAttempts();
}

function showResults() {
  showScreen('results');
  const qs = state.questions;
  const total = qs.length;
  let correct = 0, answered = 0;
  const lecBreakdown = {};
  qs.forEach((item, i) => {
    const chosen = state.answers[i];
    if (chosen === undefined) return;
    answered++;
    let ok;
    if (item.type === 'saq') {
      ok = chosen === 'got';
    } else {
      const correctIdx = ['A','B','C','D','E'].indexOf(item.q[2]);
      ok = chosen === correctIdx;
    }
    if (ok) correct++;
    if (!lecBreakdown[item.lecture]) lecBreakdown[item.lecture] = {answered:0, correct:0, total: qs.filter(q=>q.lecture===item.lecture).length};
    lecBreakdown[item.lecture].answered++;
    if (ok) lecBreakdown[item.lecture].correct++;
  });
  const pct = answered ? Math.round(correct/answered*100) : 0;
  const bannerCls = pct >= 70 ? 'result-good' : pct >= 50 ? 'result-mid' : 'result-bad';
  const msg = pct >= 70 ? '🎉 Well done!' : pct >= 50 ? '📚 Keep revising' : '⚠️ Focus needed';

  let tableRows = '';
  if (state.isAllRandom) {
    // Group lectures by block for all-random mode
    const blockGroups = {};
    qs.forEach(item => {
      if (!blockGroups[item.blockName]) blockGroups[item.blockName] = [];
      if (!blockGroups[item.blockName].includes(item.lecture)) blockGroups[item.blockName].push(item.lecture);
    });
    Object.entries(blockGroups).forEach(([blockName, lecs]) => {
      tableRows += `<tr><td colspan="5" style="background:var(--bg-1);font-size:12px;font-weight:600;color:var(--ink-dim);padding:4px 8px;letter-spacing:0.05em">${blockName}</td></tr>`;
      lecs.forEach(lec => {
        const d = lecBreakdown[lec];
        if (!d) return;
        const p = d.answered ? Math.round(d.correct/d.answered*100) : null;
        const lost = d.answered - d.correct;
        const barCls = p === null ? '' : p >= 70 ? 'bar-g' : p >= 50 ? 'bar-a' : 'bar-r';
        tableRows += `<tr>
          <td style="max-width:220px;font-size:13px;padding-left:16px">${lec}</td>
          <td style="text-align:center;font-size:12px">${d.total}</td>
          <td style="text-align:center;font-size:12px">${d.answered}</td>
          <td style="text-align:center"><span class="lost-badge ${lost>0?'lost-bad':'lost-ok'}">${lost||'–'}</span></td>
          <td style="min-width:110px">
            ${p !== null ? `<div class="bar-cell"><div class="bar-bg"><div class="bar-fill ${barCls}" style="width:${p}%"></div></div><span class="pct-label">${p}%</span></div>` : '<span style="font-size:12px;color:var(--text3)">–</span>'}
          </td>
        </tr>`;
      });
    });
  } else {
    Object.entries(lecBreakdown).forEach(([lec, d]) => {
      const p = d.answered ? Math.round(d.correct/d.answered*100) : null;
      const lost = d.answered - d.correct;
      const barCls = p === null ? '' : p >= 70 ? 'bar-g' : p >= 50 ? 'bar-a' : 'bar-r';
      tableRows += `<tr>
        <td style="max-width:220px;font-size:13px">${lec}</td>
        <td style="text-align:center;font-size:12px">${d.total}</td>
        <td style="text-align:center;font-size:12px">${d.answered}</td>
        <td style="text-align:center"><span class="lost-badge ${lost>0?'lost-bad':'lost-ok'}">${lost||'–'}</span></td>
        <td style="min-width:110px">
          ${p !== null ? `<div class="bar-cell"><div class="bar-bg"><div class="bar-fill ${barCls}" style="width:${p}%"></div></div><span class="pct-label">${p}%</span></div>` : '<span style="font-size:12px;color:var(--text3)">–</span>'}
        </td>
      </tr>`;
    });
  }

  let avgTimeStat = '';
  if (timerEnabled) {
    const times = Object.values(state.questionTimes);
    if (times.length > 0) {
      const avgSecs = Math.round(times.reduce((a, b) => a + b, 0) / times.length);
      const tm = Math.floor(avgSecs / 60), ts = avgSecs % 60;
      avgTimeStat = `<div class="scard"><div class="n" style="font-size:18px">${tm}:${String(ts).padStart(2,'0')}</div><div class="l">Avg / question</div></div>`;
    }
  }

  document.getElementById('resContent').innerHTML = `
    <div class="result-banner ${bannerCls}">
      <div class="result-score">${answered ? pct + '%' : '–'}</div>
      <div class="result-label">${msg} · ${correct}/${answered} correct · ${total - answered} unanswered</div>
    </div>
    <div class="stat-grid">
      <div class="scard"><div class="n">${total}</div><div class="l">Questions</div></div>
      <div class="scard"><div class="n">${answered}</div><div class="l">Answered</div></div>
      <div class="scard"><div class="n">${correct}</div><div class="l">Correct</div></div>
      <div class="scard"><div class="n" style="color:${pct>=70?'var(--green)':pct>=50?'#BA7517':'var(--red)'}">${answered?pct+'%':'–'}</div><div class="l">Score</div></div>
      ${avgTimeStat}
    </div>
    <div class="lec-breakdown">
      <h3>Marks lost by lecture — focus your revision here</h3>
      <div style="overflow-x:auto;margin-top:0.75rem">
      <table class="ltable">
        <thead><tr><th>Lecture</th><th>Total</th><th>Done</th><th>Lost</th><th>Score</th></tr></thead>
        <tbody>${tableRows}</tbody>
      </table></div>
    </div>`;
}

function reviewAnswers() {
  showScreen('review');
  const qs = state.questions;
  let html = '';
  qs.forEach((item, i) => {
    const chosen = state.answers[i];
    if (item.type === 'saq') {
      const q = SAQ_QUESTIONS[item.saqIdx];
      const ratingLabel = chosen === 'got' ? '✓ Got it' : chosen === 'partial' ? '~ Partial' : chosen === 'missed' ? '✗ Missed' : '⬜ Unanswered';
      const ratingCls   = chosen === 'got' ? 'rev-correct' : chosen === 'partial' ? 'rev-partial' : chosen === 'missed' ? 'rev-wrong' : '';
      html += `<div class="rev-q">
        <div style="display:flex;justify-content:space-between;align-items:baseline;margin-bottom:6px">
          <span class="lec-tag">${q.topic}</span>
          <span class="${ratingCls}" style="font-size:12px">${ratingLabel}</span>
        </div>
        <div class="rev-q-text">${i+1}. ${q.question}</div>
        <details class="saq-rev-details"><summary>Model answer</summary>
          <div class="saq-model-answer" style="margin-top:6px">${q.answer}</div>
        </details>
      </div>`;
      return;
    }
    const [text, opts, correct, expl] = item.q;
    const correctIdx = ['A','B','C','D','E'].indexOf(correct);
    const isOk = chosen !== undefined && chosen === correctIdx;
    const status = chosen === undefined ? '⬜ Unanswered' : isOk ? '✓ Correct' : '✗ Incorrect';
    const statusCls = chosen === undefined ? '' : isOk ? 'rev-correct' : 'rev-wrong';

    html += `<div class="rev-q">
      <div style="display:flex;justify-content:space-between;align-items:baseline;margin-bottom:6px">
        <span class="lec-tag">${item.lecture}</span>
        <span class="rev-answer ${statusCls}" style="font-size:12px">${status}</span>
      </div>
      <div class="rev-q-text">${i+1}. ${text}</div>
      <div style="font-size:13px;margin-top:6px">
        <span style="background:var(--green-bg);color:var(--green-text);padding:2px 7px;border-radius:4px;font-size:12px">
          ✓ ${String.fromCharCode(65+correctIdx)}. ${opts[correctIdx]}
        </span>
        ${chosen !== undefined && !isOk ? `<span style="background:var(--red-bg);color:var(--red-text);padding:2px 7px;border-radius:4px;font-size:12px;margin-left:6px">
          ✗ You chose: ${String.fromCharCode(65+chosen)}. ${opts[chosen]}
        </span>` : ''}
      </div>
      <div class="rev-note">${expl}</div>
    </div>`;
  });
  document.getElementById('revContent').innerHTML = html;
}

// ═══════════════════════════════════════════════════════════════
// HISTORY
// ═══════════════════════════════════════════════════════════════
function showHistory() {
  showScreen('history');
  const h = document.getElementById('hContent');
  if (!allAttempts.length) {
    h.innerHTML = '<div class="empty-state">No attempts yet. Complete a quiz to see your history here.</div>';
    return;
  }
  // Group by block
  const grouped = {};
  allAttempts.forEach(a => {
    if (!grouped[a.blockId]) grouped[a.blockId] = [];
    grouped[a.blockId].push(a);
  });

  let html = '';
  Object.entries(grouped).forEach(([bid, attempts]) => {
    const b = BLOCKS[bid];
    const blockName = b ? b.name : 'All Blocks';
    const blockColor = b ? b.color : '#888';
    html += `<h3 style="margin:1.2rem 0 0.5rem;font-size:14px;color:${blockColor}">${blockName}</h3>`;

    // Trend chart
    const scores = attempts.map(a => a.pct);
    const maxScore = Math.max(...scores, 1);
    const chartBars = scores.map((s, i) => {
      const h = Math.max(4, Math.round((s/maxScore)*100));
      const cls = s >= 70 ? 'bar-g' : s >= 50 ? 'bar-a' : 'bar-r';
      return `<div class="trend-bar bar-fill ${cls}" style="height:${h}%;flex:1;min-width:8px;border-radius:3px 3px 0 0;max-width:32px" title="${s}% — ${new Date(attempts[i].date).toLocaleDateString()}"></div>`;
    }).join('');
    html += `<div class="trend-chart" title="Score trend (older → newer)">${chartBars}</div>`;

    html += `<table class="htable" style="width:100%;margin-bottom:1rem">
      <thead><tr><th>Date</th><th>Score</th><th>Correct</th><th>Mode</th><th>Qs</th><th>Avg time</th><th></th></tr></thead><tbody>`;
    [...attempts].reverse().forEach(a => {
      const date = new Date(a.date).toLocaleDateString('en-GB', {day:'numeric',month:'short',year:'2-digit',hour:'2-digit',minute:'2-digit'});
      const pillCls = a.pct >= 70 ? 'pill-g' : a.pct >= 50 ? 'pill-a' : 'pill-r';
      let avgTimeCell = '<td style="font-size:11px;color:var(--ink-dim)">—</td>';
      if (a.avgTimeSecs != null) {
        const tm = Math.floor(a.avgTimeSecs / 60), ts = a.avgTimeSecs % 60;
        avgTimeCell = `<td style="font-size:11px;font-family:'JetBrains Mono',monospace">${tm}:${String(ts).padStart(2,'0')}</td>`;
      }
      html += `<tr>
        <td style="font-size:11px">${date}</td>
        <td><span class="score-pill ${pillCls}">${a.pct}%</span></td>
        <td style="font-size:12px">${a.correct}/${a.answered}</td>
        <td style="font-size:11px">${a.isRandom ? '🎲 Random' : 'All'}</td>
        <td style="font-size:12px">${a.total}</td>
        ${avgTimeCell}
        <td><button class="del-attempt" onclick="deleteAttempt('${a.id}')" title="Delete attempt">✕</button></td>
      </tr>`;
    });
    html += '</tbody></table>';
  });

  h.innerHTML = html;
}

// ═══════════════════════════════════════════════════════════════
// STATS HELPERS
// ═══════════════════════════════════════════════════════════════
function filterAttemptsByTime(attempts, period) {
  if (period === 'all') return attempts;
  const cutoff = Date.now() - (period === '7d' ? 7 : 30) * 864e5;
  return attempts.filter(a => new Date(a.date).getTime() >= cutoff);
}

function computeTopicStats(attempts) {
  const topics = {};
  for (const a of attempts) {
    for (const [lec, s] of Object.entries(a.breakdown || {})) {
      if (!topics[lec]) topics[lec] = { answered: 0, correct: 0 };
      topics[lec].answered += s.answered;
      topics[lec].correct  += s.correct;
    }
  }
  return Object.entries(topics)
    .filter(([, s]) => s.answered > 0)
    .map(([name, s]) => ({ name, pct: Math.round(s.correct / s.answered * 100), answered: s.answered, correct: s.correct }))
    .sort((a, b) => a.pct - b.pct);
}

function generateRecommendations(topicStats, attempts) {
  const recs = [];
  topicStats.filter(t => t.pct < 50).slice(0, 3).forEach(t =>
    recs.push('Revise "' + t.name + '" \u2014 ' + t.pct + '% accuracy')
  );
  const recent = attempts.slice(-3);
  if (recent.length === 3 && recent.every(a => a.pct < 60))
    recs.push('Retake the quiz \u2014 last 3 attempts averaged below 60%');
  const last5 = attempts.slice(-5);
  if (last5.length >= 3) {
    const trend = last5[last5.length - 1].pct - last5[0].pct;
    if (trend > 10)  recs.push('Great improvement \u2014 keep going!');
    else if (trend < -10) recs.push('Scores declining \u2014 consider reviewing recent topics');
  }
  return recs.length ? recs : ['All topics look solid. Keep practising!'];
}

let trendChartInstance = null;
let topicChartInstance = null;

// ═══════════════════════════════════════════════════════════════
// SUMMARY STATS
// ═══════════════════════════════════════════════════════════════
function showAllStats() {
  showScreen('stats');
  const tabs = document.getElementById('sTabs');
  tabs.innerHTML = '';
  const firstId = Object.keys(BLOCKS)[0];
  Object.entries(BLOCKS).forEach(([id, b]) => {
    const t = document.createElement('button');
    t.className = 'tab' + (id === firstId ? ' on' : '');
    t.textContent = b.name;
    t.onclick = () => {
      document.querySelectorAll('.tab').forEach(x => x.classList.remove('on'));
      t.classList.add('on');
      statsSortOrder = 'default';
      statsPeriod = 'all';
      renderStats(id);
    };
    tabs.appendChild(t);
  });

  // All Random tab
  const arTab = document.createElement('button');
  arTab.className = 'tab';
  arTab.textContent = 'All Random';
  arTab.onclick = () => {
    document.querySelectorAll('.tab').forEach(x => x.classList.remove('on'));
    arTab.classList.add('on');
    statsPeriod = 'all';
    renderAllRandomStats();
  };
  tabs.appendChild(arTab);

  // SAQ tab
  const saqTab = document.createElement('button');
  saqTab.className = 'tab';
  saqTab.textContent = 'SAQ';
  saqTab.onclick = () => {
    document.querySelectorAll('.tab').forEach(x => x.classList.remove('on'));
    saqTab.classList.add('on');
    renderSaqStats();
  };
  tabs.appendChild(saqTab);

  renderStats(firstId);
}

// Sort state for summary stats: 'default' | 'asc' | 'desc'
let statsSortOrder = 'default';
// Time filter for summary stats: 'all' | '30d' | '7d'
let statsPeriod = 'all';

function renderStats(blockId, period) {
  if (period !== undefined) statsPeriod = period;
  const p = statsPeriod;

  // --- Cumulative lecture stats (all-time, for the breakdown table) ---
  const b = BLOCKS[blockId];
  const s = allStats[blockId] || {};
  let totalQ = 0, totalAns = 0, totalCor = 0;
  Object.values(b.lectures).forEach(qs => totalQ += qs.length);
  Object.values(s).forEach(ls => { totalAns += ls.answered; totalCor += ls.correct; });
  const overallPct = totalAns ? Math.round(totalCor / totalAns * 100) : null;

  // --- Attempt-based stats (time-filtered) ---
  const blockAttempts = filterAttemptsByTime(
    allAttempts.filter(a => a.blockId === blockId), p
  ).sort((a, bv) => new Date(a.date) - new Date(bv.date));
  const topicStats = computeTopicStats(blockAttempts);
  const recs = generateRecommendations(topicStats, blockAttempts);
  const avgScore  = blockAttempts.length ? Math.round(blockAttempts.reduce((acc, a) => acc + a.pct, 0) / blockAttempts.length) : null;
  const bestScore = blockAttempts.length ? Math.max(...blockAttempts.map(a => a.pct)) : null;
  const weakest   = topicStats.length ? topicStats[0].name : '\u2014';

  // --- Lecture breakdown table (sort logic unchanged) ---
  let lecData = Object.entries(b.lectures).map(([lec, qs]) => {
    const ls = s[lec] || { answered: 0, correct: 0 };
    const lp = ls.answered ? Math.round(ls.correct / ls.answered * 100) : null;
    return { lec, qs, ls, p: lp };
  });
  if (statsSortOrder === 'asc') {
    lecData.sort((a, bv) => {
      if (a.p === null && bv.p === null) return 0;
      if (a.p === null) return 1;
      if (bv.p === null) return 1;
      return a.p - bv.p;
    });
  } else if (statsSortOrder === 'desc') {
    lecData.sort((a, bv) => {
      if (a.p === null && bv.p === null) return 0;
      if (a.p === null) return 1;
      if (bv.p === null) return 1;
      return bv.p - a.p;
    });
  }
  const sortLabels = { default: '\u2195 Sort by score', asc: '\u2191 Lowest first', desc: '\u2193 Highest first' };
  const nextSort   = { default: 'asc', asc: 'desc', desc: 'default' };

  let rows = '';
  lecData.forEach(({ lec, qs, ls, p: lp }) => {
    const lost = ls.answered - ls.correct;
    const barCls = lp === null ? '' : lp >= 70 ? 'bar-g' : lp >= 50 ? 'bar-a' : 'bar-r';
    rows += '<tr>' +
      '<td style="font-size:13px;max-width:220px">' + lec + '</td>' +
      '<td style="text-align:center;font-size:12px">' + qs.length + '</td>' +
      '<td style="text-align:center;font-size:12px">' + ls.answered + '</td>' +
      '<td style="text-align:center"><span class="lost-badge ' + (lost > 0 && ls.answered > 0 ? 'lost-bad' : 'lost-ok') + '">' + (lost && ls.answered ? lost : '\u2013') + '</span></td>' +
      '<td style="min-width:110px">' +
        (lp !== null
          ? '<div class="bar-cell"><div class="bar-bg"><div class="bar-fill ' + barCls + '" style="width:' + lp + '%"></div></div><span class="pct-label">' + lp + '%</span></div>'
          : '<span style="font-size:12px;color:var(--text3)">\u2013</span>') +
      '</td></tr>';
  });

  // --- Attempt history rows ---
  let attemptRows = '';
  [...blockAttempts].reverse().forEach(a => {
    const pillCls = a.pct >= 70 ? 'bar-g' : a.pct >= 50 ? 'bar-a' : 'bar-r';
    attemptRows += '<tr>' +
      '<td>' + new Date(a.date).toLocaleDateString() + '</td>' +
      '<td><span class="pill ' + pillCls + '">' + a.pct + '%</span></td>' +
      '<td>' + a.correct + '/' + a.answered + '</td>' +
      '<td>' + (a.isRandom ? 'Random' : 'Sequential') + '</td>' +
      '</tr>';
  });

  document.getElementById('sContent').innerHTML =
    // Time filters
    '<div class="time-filters">' +
      ['7d', '30d', 'all'].map(pv =>
        '<button class="tf-btn' + (p === pv ? ' active' : '') + '" onclick="renderStats(\'' + blockId + '\',\'' + pv + '\')">' +
        (pv === 'all' ? 'All time' : pv) + '</button>'
      ).join('') +
    '</div>' +

    // Key stats row
    '<div class="stat-grid">' +
      '<div class="scard"><div class="n">' + (avgScore !== null ? avgScore + '%' : '\u2013') + '</div><div class="l">Avg Score</div></div>' +
      '<div class="scard"><div class="n">' + (bestScore !== null ? bestScore + '%' : '\u2013') + '</div><div class="l">Best Score</div></div>' +
      '<div class="scard"><div class="n">' + blockAttempts.length + '</div><div class="l">Attempts</div></div>' +
      '<div class="scard"><div class="n" style="font-size:' + (weakest.length > 20 ? '0.7rem' : '0.85rem') + ';line-height:1.2">' + weakest + '</div><div class="l">Weakest Topic</div></div>' +
    '</div>' +

    // Charts (only if attempts exist)
    (blockAttempts.length > 0
      ? '<div class="chart-section"><h3>Score Trend</h3><canvas id="trendChart" height="120"></canvas></div>' +
        '<div class="chart-section"><h3>Topic Accuracy</h3><canvas id="topicChart" height="' + Math.max(topicStats.length * 30, 120) + '"></canvas></div>'
      : '<div class="chart-section" style="color:var(--ink-dim);font-size:14px;padding:1.25rem">Complete some quiz attempts to see charts here.</div>'
    ) +

    // Recommendations
    '<div class="recs-panel"><h3>Recommendations</h3><ul>' +
      recs.map(r => '<li>' + r + '</li>').join('') +
    '</ul></div>' +

    // Individual attempts table
    (blockAttempts.length > 0
      ? '<div class="chart-section"><h3>Individual Attempts</h3>' +
        '<div style="overflow-x:auto"><table class="htable">' +
        '<thead><tr><th>Date</th><th>Score</th><th>Correct</th><th>Mode</th></tr></thead>' +
        '<tbody>' + attemptRows + '</tbody></table></div></div>'
      : ''
    ) +

    // Lecture breakdown (all-time, unchanged)
    '<div class="chart-section">' +
    '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:0.75rem;gap:12px;flex-wrap:wrap">' +
      '<div>' +
        '<h3 style="margin:0 0 0.25rem">Lecture Breakdown</h3>' +
        '<p style="font-size:13px;color:var(--ink-dim);margin:0">All-time \u2014 marks lost by lecture:</p>' +
      '</div>' +
      '<button class="sort-btn ' + (statsSortOrder !== 'default' ? 'sort-btn-active' : '') + '" ' +
        'onclick="statsSortOrder=\'' + nextSort[statsSortOrder] + '\'; renderStats(\'' + blockId + '\')" ' +
        'title="Cycle sort: lecture order \u2192 lowest % first \u2192 highest % first">' +
        sortLabels[statsSortOrder] +
      '</button>' +
    '</div>' +
    '<div style="overflow-x:auto"><table class="ltable">' +
      '<thead><tr><th>Lecture</th><th>Total Qs</th><th>Attempted</th><th>Marks lost</th><th>Score</th></tr></thead>' +
      '<tbody>' + rows + '</tbody>' +
    '</table></div></div>';

  // Render Chart.js charts
  if (blockAttempts.length > 0) {
    if (trendChartInstance) { trendChartInstance.destroy(); trendChartInstance = null; }
    if (topicChartInstance) { topicChartInstance.destroy(); topicChartInstance = null; }

    trendChartInstance = new Chart(document.getElementById('trendChart'), {
      type: 'line',
      data: {
        labels: blockAttempts.map(a => new Date(a.date).toLocaleDateString()),
        datasets: [{
          label: 'Score %',
          data: blockAttempts.map(a => a.pct),
          borderColor: '#6366f1',
          backgroundColor: 'rgba(99,102,241,0.1)',
          tension: 0.3,
          fill: true,
          pointRadius: 4,
          pointHoverRadius: 6
        }]
      },
      options: {
        responsive: true,
        scales: { y: { min: 0, max: 100, ticks: { callback: v => v + '%' } } },
        plugins: { legend: { display: false }, tooltip: { callbacks: { label: ctx => ctx.parsed.y + '%' } } }
      }
    });

    topicChartInstance = new Chart(document.getElementById('topicChart'), {
      type: 'bar',
      data: {
        labels: topicStats.map(t => t.name),
        datasets: [{
          data: topicStats.map(t => t.pct),
          backgroundColor: topicStats.map(t => t.pct >= 70 ? '#22c55e' : t.pct >= 50 ? '#f59e0b' : '#ef4444')
        }]
      },
      options: {
        indexAxis: 'y',
        responsive: true,
        scales: { x: { min: 0, max: 100, ticks: { callback: v => v + '%' } } },
        plugins: { legend: { display: false }, tooltip: { callbacks: { label: ctx => ctx.parsed.x + '%' } } }
      }
    });
  }
}

function renderAllRandomStats(period) {
  if (period !== undefined) statsPeriod = period;
  const p = statsPeriod;

  const attempts = filterAttemptsByTime(
    allAttempts.filter(a => a.blockId === 'all'), p
  ).sort((a, b) => new Date(a.date) - new Date(b.date));

  const topicStats = computeTopicStats(attempts);
  const recs = generateRecommendations(topicStats, attempts);
  const avgScore  = attempts.length ? Math.round(attempts.reduce((acc, a) => acc + a.pct, 0) / attempts.length) : null;
  const bestScore = attempts.length ? Math.max(...attempts.map(a => a.pct)) : null;
  const totalQsAnswered = attempts.reduce((acc, a) => acc + a.answered, 0);
  const weakest = topicStats.length ? topicStats[0].name : '\u2014';

  let attemptRows = '';
  [...attempts].reverse().forEach(a => {
    const pillCls = a.pct >= 70 ? 'bar-g' : a.pct >= 50 ? 'bar-a' : 'bar-r';
    attemptRows += '<tr>' +
      '<td>' + new Date(a.date).toLocaleDateString() + '</td>' +
      '<td><span class="pill ' + pillCls + '">' + a.pct + '%</span></td>' +
      '<td>' + a.correct + '/' + a.answered + '</td>' +
      '<td>' + a.total + ' Qs</td>' +
      '</tr>';
  });

  // Build topic breakdown rows (grouped by lecture, sorted by accuracy)
  let topicRows = '';
  topicStats.forEach(t => {
    const lost = t.answered - t.correct;
    const barCls = t.pct >= 70 ? 'bar-g' : t.pct >= 50 ? 'bar-a' : 'bar-r';
    topicRows += '<tr>' +
      '<td style="font-size:13px;max-width:220px">' + t.name + '</td>' +
      '<td style="text-align:center;font-size:12px">' + t.answered + '</td>' +
      '<td style="text-align:center"><span class="lost-badge ' + (lost > 0 ? 'lost-bad' : 'lost-ok') + '">' + (lost || '\u2013') + '</span></td>' +
      '<td style="min-width:110px"><div class="bar-cell"><div class="bar-bg"><div class="bar-fill ' + barCls + '" style="width:' + t.pct + '%"></div></div><span class="pct-label">' + t.pct + '%</span></div></td>' +
      '</tr>';
  });

  document.getElementById('sContent').innerHTML =
    // Time filters
    '<div class="time-filters">' +
      ['7d', '30d', 'all'].map(pv =>
        '<button class="tf-btn' + (p === pv ? ' active' : '') + '" onclick="renderAllRandomStats(\'' + pv + '\')">' +
        (pv === 'all' ? 'All time' : pv) + '</button>'
      ).join('') +
    '</div>' +

    '<div class="stat-grid">' +
      '<div class="scard"><div class="n">' + (avgScore !== null ? avgScore + '%' : '\u2013') + '</div><div class="l">Avg Score</div></div>' +
      '<div class="scard"><div class="n">' + (bestScore !== null ? bestScore + '%' : '\u2013') + '</div><div class="l">Best Score</div></div>' +
      '<div class="scard"><div class="n">' + attempts.length + '</div><div class="l">Attempts</div></div>' +
      '<div class="scard"><div class="n">' + totalQsAnswered + '</div><div class="l">Qs Answered</div></div>' +
    '</div>' +

    (attempts.length > 0
      ? '<div class="chart-section"><h3>Score Trend</h3><canvas id="trendChart" height="120"></canvas></div>' +
        (topicStats.length > 0 ? '<div class="chart-section"><h3>Topic Accuracy</h3><canvas id="topicChart" height="' + Math.max(topicStats.length * 30, 120) + '"></canvas></div>' : '')
      : '<div class="chart-section" style="color:var(--ink-dim);font-size:14px;padding:1.25rem">Complete some All Random attempts to see charts here.</div>'
    ) +

    '<div class="recs-panel"><h3>Recommendations</h3><ul>' +
      recs.map(r => '<li>' + r + '</li>').join('') +
    '</ul></div>' +

    (attempts.length > 0
      ? '<div class="chart-section"><h3>Individual Attempts</h3>' +
        '<div style="overflow-x:auto"><table class="htable">' +
        '<thead><tr><th>Date</th><th>Score</th><th>Correct</th><th>Size</th></tr></thead>' +
        '<tbody>' + attemptRows + '</tbody></table></div></div>'
      : ''
    ) +

    (topicStats.length > 0
      ? '<div class="chart-section"><h3>Topic Breakdown</h3>' +
        '<p style="font-size:13px;color:var(--ink-dim);margin:0 0 0.75rem">Accuracy across all lectures seen in All Random mode — sorted lowest first:</p>' +
        '<div style="overflow-x:auto"><table class="ltable">' +
        '<thead><tr><th>Lecture</th><th>Attempted</th><th>Marks lost</th><th>Score</th></tr></thead>' +
        '<tbody>' + topicRows + '</tbody></table></div></div>'
      : ''
    );

  if (attempts.length > 0) {
    if (trendChartInstance) { trendChartInstance.destroy(); trendChartInstance = null; }
    if (topicChartInstance) { topicChartInstance.destroy(); topicChartInstance = null; }

    trendChartInstance = new Chart(document.getElementById('trendChart'), {
      type: 'line',
      data: {
        labels: attempts.map(a => new Date(a.date).toLocaleDateString()),
        datasets: [{
          label: 'Score %',
          data: attempts.map(a => a.pct),
          borderColor: '#6366f1',
          backgroundColor: 'rgba(99,102,241,0.1)',
          tension: 0.3,
          fill: true,
          pointRadius: 4,
          pointHoverRadius: 6
        }]
      },
      options: {
        responsive: true,
        scales: { y: { min: 0, max: 100, ticks: { callback: v => v + '%' } } },
        plugins: { legend: { display: false }, tooltip: { callbacks: { label: ctx => ctx.parsed.y + '%' } } }
      }
    });

    if (topicStats.length > 0) {
      topicChartInstance = new Chart(document.getElementById('topicChart'), {
        type: 'bar',
        data: {
          labels: topicStats.map(t => t.name),
          datasets: [{
            data: topicStats.map(t => t.pct),
            backgroundColor: topicStats.map(t => t.pct >= 70 ? '#22c55e' : t.pct >= 50 ? '#f59e0b' : '#ef4444')
          }]
        },
        options: {
          indexAxis: 'y',
          responsive: true,
          scales: { x: { min: 0, max: 100, ticks: { callback: v => v + '%' } } },
          plugins: { legend: { display: false }, tooltip: { callbacks: { label: ctx => ctx.parsed.x + '%' } } }
        }
      });
    }
  }
}

function renderSaqStats() {
  const el = document.getElementById('sContent');

  if (!allSaqAttempts.length) {
    el.innerHTML = '<p style="color:var(--ink-dim);padding:24px 0">No SAQ sessions yet — complete a High Yield SocPop session to see your stats here.</p>';
    return;
  }

  // ── Overall totals ──
  const totSessions = allSaqAttempts.length;
  const totQs    = allSaqAttempts.reduce((s, a) => s + a.total, 0);
  const totGot   = allSaqAttempts.reduce((s, a) => s + a.got, 0);
  const totPart  = allSaqAttempts.reduce((s, a) => s + a.partial, 0);
  const totMiss  = allSaqAttempts.reduce((s, a) => s + a.missed, 0);
  const totMarks = allSaqAttempts.reduce((s, a) => s + a.marks, 0);
  const totMax   = allSaqAttempts.reduce((s, a) => s + a.maxMarks, 0);
  const avgPct   = allSaqAttempts.length ? Math.round(allSaqAttempts.reduce((s, a) => s + a.pct, 0) / allSaqAttempts.length) : 0;
  const bestPct  = allSaqAttempts.length ? Math.max(...allSaqAttempts.map(a => a.pct)) : 0;

  // ── Per-topic breakdown ──
  const topicMap = {};
  allSaqAttempts.forEach(a => {
    (a.results || []).forEach(r => {
      if (!topicMap[r.topic]) topicMap[r.topic] = { got: 0, partial: 0, missed: 0, attempts: 0 };
      topicMap[r.topic][r.rating]++;
      topicMap[r.topic].attempts++;
    });
  });
  const topicRows = Object.entries(topicMap)
    .map(([topic, d]) => ({ topic, ...d, pct: Math.round(d.got / d.attempts * 100) }))
    .sort((a, b) => a.pct - b.pct);

  const topicTableRows = topicRows.map(t => {
    const cls = t.pct >= 70 ? 'ok' : t.pct >= 50 ? 'mid' : 'bad';
    return `<tr class="saq-topic-row">
      <td>${t.topic}</td>
      <td style="text-align:center">${t.attempts}</td>
      <td style="text-align:center;color:var(--ok)">${t.got}</td>
      <td style="text-align:center;color:var(--amber-text)">${t.partial}</td>
      <td style="text-align:center;color:var(--bad)">${t.missed}</td>
      <td style="text-align:center" class="saq-acc-${cls}">${t.pct}%</td>
    </tr>`;
  }).join('');

  // ── Most-missed questions ──
  const qMap = {};
  allSaqAttempts.forEach(a => {
    (a.results || []).forEach(r => {
      if (!qMap[r.id]) qMap[r.id] = { got: 0, partial: 0, missed: 0, attempts: 0, topic: r.topic };
      qMap[r.id][r.rating]++;
      qMap[r.id].attempts++;
    });
  });
  const worst = Object.entries(qMap)
    .map(([id, d]) => ({ id: +id, ...d, pct: Math.round(d.got / d.attempts * 100) }))
    .filter(x => x.attempts >= 2)
    .sort((a, b) => a.pct - b.pct)
    .slice(0, 10);

  const worstHtml = worst.length ? worst.map(w => {
    const q = SAQ_QUESTIONS.find(sq => sq.id === w.id);
    const qText = q ? q.question.replace(/<[^>]*>/g, '').trim() : '(unknown)';
    return `<div class="saq-miss-item">
      <div class="saq-miss-topic">${w.topic}</div>
      <div class="saq-miss-q">${qText}</div>
      <div class="saq-miss-stats">
        <span style="color:var(--ok)">✓ ${w.got}</span> &nbsp;
        <span style="color:var(--amber-text)">~ ${w.partial}</span> &nbsp;
        <span style="color:var(--bad)">✗ ${w.missed}</span> &nbsp;
        <span style="opacity:.6">(${w.attempts} attempts, ${w.pct}% got)</span>
      </div>
    </div>`;
  }).join('') : '<p style="color:var(--ink-dim);font-size:.9rem">Answer each question at least twice to see weak spots.</p>';

  // ── Session history ──
  const histRows = [...allSaqAttempts].reverse().map((a, i) => {
    const d = new Date(a.date);
    const dateStr = d.toLocaleDateString('en-GB', { day: 'numeric', month: 'short' }) + ' ' + d.toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit' });
    const filterLabel = a.filter === 'pop' ? 'Pop' : a.filter === 'soc' ? 'Soc' : 'All';
    const retestTag = a.isRetest ? ' <span class="saq-retest-tag">Retest</span>' : '';
    const pctCls = a.pct >= 70 ? 'ok' : a.pct >= 50 ? 'mid' : 'bad';
    return `<tr>
      <td>${dateStr}</td>
      <td>${filterLabel}${retestTag}</td>
      <td style="text-align:center">${a.total}</td>
      <td style="text-align:center" class="saq-acc-${pctCls}">${a.pct}%</td>
      <td style="text-align:center;color:var(--ok)">${a.got}</td>
      <td style="text-align:center;color:var(--amber-text)">${a.partial}</td>
      <td style="text-align:center;color:var(--bad)">${a.missed}</td>
    </tr>`;
  }).join('');

  el.innerHTML = `
    <div class="stat-grid" style="margin-bottom:24px">
      <div class="scard"><div class="n">${totSessions}</div><div class="l">Sessions</div></div>
      <div class="scard"><div class="n">${totQs}</div><div class="l">Questions</div></div>
      <div class="scard"><div class="n">${avgPct}%</div><div class="l">Avg Marks</div></div>
      <div class="scard"><div class="n">${bestPct}%</div><div class="l">Best Session</div></div>
    </div>
    <div class="stat-grid" style="margin-bottom:32px">
      <div class="scard"><div class="n" style="color:var(--ok)">${totGot}</div><div class="l">Got it</div></div>
      <div class="scard"><div class="n" style="color:var(--amber-text)">${totPart}</div><div class="l">Partial</div></div>
      <div class="scard"><div class="n" style="color:var(--bad)">${totMiss}</div><div class="l">Missed</div></div>
      <div class="scard"><div class="n">${totMax ? Math.round(totMarks / totMax * 100) : 0}%</div><div class="l">Overall Marks</div></div>
    </div>

    <h3 class="stat-section-hd">Topic Breakdown</h3>
    <div style="overflow-x:auto;margin-bottom:32px">
      <table class="htable">
        <thead><tr><th>Topic</th><th style="text-align:center">Attempts</th><th style="text-align:center">Got</th><th style="text-align:center">Part</th><th style="text-align:center">Missed</th><th style="text-align:center">Acc.</th></tr></thead>
        <tbody>${topicTableRows}</tbody>
      </table>
    </div>

    <h3 class="stat-section-hd">Most Missed Questions</h3>
    <div class="saq-miss-list" style="margin-bottom:32px">${worstHtml}</div>

    <h3 class="stat-section-hd">Session History</h3>
    <div style="overflow-x:auto">
      <table class="htable">
        <thead><tr><th>Date</th><th>Topic</th><th style="text-align:center">Qs</th><th style="text-align:center">Marks %</th><th style="text-align:center">Got</th><th style="text-align:center">Part</th><th style="text-align:center">Missed</th></tr></thead>
        <tbody>${histRows}</tbody>
      </table>
    </div>`;
}

// ═══════════════════════════════════════════════════════════════
// HIGH YIELD SOCPOP — SAQ MODE LOGIC
// ═══════════════════════════════════════════════════════════════

// SAQ spaced-repetition
const SAQ_RECENT_KEY = 'p1quiz_saq_recent';
const SAQ_RECENT_MAX = 65;
function loadSaqRecent() { return load(SAQ_RECENT_KEY, []); }
function saveSaqRecent(arr) { save(SAQ_RECENT_KEY, arr); }
function addRecentSaq(id) {
  let arr = loadSaqRecent();
  arr = arr.filter(x => x !== id);
  arr.push(id);
  if (arr.length > SAQ_RECENT_MAX) arr = arr.slice(-SAQ_RECENT_MAX);
  saveSaqRecent(arr);
}
function sortSaqPoolByRecency(pool) {
  const recent = loadSaqRecent();
  const fresh = pool.filter(i => !recent.includes(SAQ_QUESTIONS[i].id));
  const seen  = pool.filter(i =>  recent.includes(SAQ_QUESTIONS[i].id));
  fisherYates(fresh);
  fisherYates(seen);
  return [...fresh, ...seen];
}

// SAQ quiz state (separate from MCQ state)
let saqState = {
  pool: [],
  index: 0,
  results: [],
  filter: 'all',
  isRetest: false
};

function openSaqPicker() {
  document.getElementById('saqPickerModal').style.display = 'flex';
}
function closeSaqPicker() {
  document.getElementById('saqPickerModal').style.display = 'none';
}

function startSaq(filter) {
  closeSaqPicker();
  // Clear MCQ state so savePartial/saveResume are no-ops while in SAQ mode
  state.questions = [];
  state.answers = {};
  const indices = SAQ_QUESTIONS.map((q, i) => i).filter(i => {
    if (filter === 'pop') return SAQ_QUESTIONS[i].topic.startsWith('Pop:');
    if (filter === 'soc') return SAQ_QUESTIONS[i].topic.startsWith('Soc:');
    return true;
  });
  saqState.pool = sortSaqPoolByRecency(indices);
  saqState.index = 0;
  saqState.results = [];
  saqState.filter = filter;
  saqState.isRetest = false;
  document.getElementById('qTitle').textContent = 'High Yield SocPop — SAQ';
  showScreen('quiz');
  renderSaqStandaloneQ();
}

function retestWeak() {
  const weakIds = saqState.results
    .filter(r => r.rating === 'partial' || r.rating === 'missed')
    .map(r => r.id);
  const indices = SAQ_QUESTIONS.map((q, i) => i).filter(i => weakIds.includes(SAQ_QUESTIONS[i].id));
  fisherYates(indices);
  state.questions = [];
  state.answers = {};
  saqState.pool = indices;
  saqState.index = 0;
  saqState.results = [];
  saqState.isRetest = true;
  document.getElementById('qTitle').textContent = 'High Yield SocPop — Retest';
  showScreen('quiz');
  renderSaqStandaloneQ();
}

function renderSaqStandaloneQ() {
  const total = saqState.pool.length;
  const i = saqState.index;
  const q = SAQ_QUESTIONS[saqState.pool[i]];
  const pct = (i / total) * 100;

  document.getElementById('qMeta').textContent = q.topic + ' · SAQ';
  document.getElementById('pFill').style.width = pct + '%';
  document.getElementById('pLeft').textContent = i + ' answered';
  document.getElementById('pRight').textContent = (i + 1) + ' / ' + total;
  document.getElementById('qCtr').textContent = 'Q' + (i + 1) + ' of ' + total;
  document.getElementById('prevBtn').disabled = true;
  document.getElementById('nextBtn').style.display = 'none';
  document.getElementById('finBtn').style.display = 'none';

  const marksText = q.marks === 1 ? '1 mark' : q.marks + ' marks';

  document.getElementById('qArea').innerHTML = `
    <div class="qcard saq-card">
      <div class="saq-header">
        <div class="lec-tag">${q.topic}</div>
        <div class="saq-marks-badge">${marksText}</div>
      </div>
      <div class="qtext">${q.question}</div>
      <div class="saq-input-area">
        <label class="saq-input-label">Your answer:</label>
        <textarea class="saq-input" id="saqTextarea" placeholder="Write your answer here..." rows="4"></textarea>
      </div>
      <button class="saq-reveal-btn" id="saqRevealBtn" onclick="revealSaqStandaloneAnswer()">Reveal Answer</button>
      <div class="saq-reveal-section" id="saqRevealSection" style="display:none">
        <div class="saq-compare-row">
          <div>
            <div class="saq-compare-label">Your answer:</div>
            <div class="saq-your-text" id="saqYourText"></div>
          </div>
          <div>
            <div class="saq-compare-label">Model answer:</div>
            <div class="saq-model-answer" id="saqModelAnswer"></div>
          </div>
        </div>
        <div class="saq-rating-row">
          <div class="saq-rating-label">How did you do?</div>
          <div class="saq-rating-btns">
            <button class="saq-rating-btn missed" onclick="rateSaqStandalone('missed')">✗ Missed</button>
            <button class="saq-rating-btn partial" onclick="rateSaqStandalone('partial')">~ Partial</button>
            <button class="saq-rating-btn got" onclick="rateSaqStandalone('got')">✓ Got it</button>
          </div>
        </div>
      </div>
    </div>`;
}

function revealSaqStandaloneAnswer() {
  const q = SAQ_QUESTIONS[saqState.pool[saqState.index]];
  const textarea = document.getElementById('saqTextarea');
  document.getElementById('saqYourText').textContent = textarea.value.trim() || '(no answer written)';
  document.getElementById('saqModelAnswer').textContent = q.answer;
  document.getElementById('saqRevealSection').style.display = '';
  document.getElementById('saqRevealBtn').style.display = 'none';
  document.getElementById('saqRevealSection').scrollIntoView({ behavior: 'smooth', block: 'nearest' });
}

function rateSaqStandalone(rating) {
  const q = SAQ_QUESTIONS[saqState.pool[saqState.index]];
  saqState.results.push({ id: q.id, rating, marks: q.marks, topic: q.topic });
  if (typeof shaderAnswerFlash === 'function') shaderAnswerFlash(rating === 'got');
  if (rating === 'got') addRecentSaq(q.id);
  saqState.index++;
  if (saqState.index >= saqState.pool.length) {
    showSaqResults();
  } else {
    renderSaqStandaloneQ();
  }
}

function showSaqResults() {
  const results = saqState.results;
  const total = results.length;
  const got     = results.filter(r => r.rating === 'got').length;
  const partial = results.filter(r => r.rating === 'partial').length;
  const missed  = results.filter(r => r.rating === 'missed').length;
  const totalMarks  = results.reduce((s, r) => s + r.marks, 0);
  const earnedMarks = results.reduce((s, r) => {
    if (r.rating === 'got')     return s + r.marks;
    if (r.rating === 'partial') return s + r.marks * 0.5;
    return s;
  }, 0);
  const marksRounded = Math.round(earnedMarks * 2) / 2;
  const pct = totalMarks ? Math.round(earnedMarks / totalMarks * 100) : 0;

  // Persist session to localStorage
  allSaqAttempts.push({
    date:     new Date().toISOString(),
    filter:   saqState.filter,
    isRetest: !!saqState.isRetest,
    total, got, partial, missed,
    marks:    marksRounded,
    maxMarks: totalMarks,
    pct,
    results: results.map(r => {
      const q = SAQ_QUESTIONS.find(sq => sq.id === r.id);
      return { id: r.id, topic: q ? q.topic : '', rating: r.rating, marks: r.marks };
    })
  });
  saveSaqAttempts();

  showScreen('saqResults');
  const bannerCls = pct >= 70 ? 'result-good' : pct >= 50 ? 'result-mid' : 'result-bad';
  const weakCount = partial + missed;
  const retestBtn = weakCount > 0
    ? `<button class="btn btn-amber" onclick="retestWeak()">↩ Retest ${weakCount} weak question${weakCount > 1 ? 's' : ''}</button>`
    : '';

  document.getElementById('saqResContent').innerHTML = `
    <div class="result-banner ${bannerCls}">
      <div class="result-score">${pct}%</div>
      <div class="result-label">${marksRounded} / ${totalMarks} marks &nbsp;·&nbsp; ${got} got it &nbsp;·&nbsp; ${partial} partial &nbsp;·&nbsp; ${missed} missed</div>
    </div>
    <div class="stat-grid">
      <div class="scard"><div class="n">${total}</div><div class="l">Questions</div></div>
      <div class="scard"><div class="n" style="color:var(--ok)">${got}</div><div class="l">Got it</div></div>
      <div class="scard"><div class="n" style="color:var(--amber-text)">${partial}</div><div class="l">Partial</div></div>
      <div class="scard"><div class="n" style="color:var(--bad)">${missed}</div><div class="l">Missed</div></div>
    </div>
    <div class="saq-results-actions">
      ${retestBtn}
      <button class="btn" onclick="showSaqReview()">Review answers</button>
      <button class="btn" onclick="startSaq(saqState.filter)">Try again</button>
      <button class="btn" onclick="showHome()">Home</button>
    </div>`;
}

function showSaqReview() {
  showScreen('saqReview');
  let html = '';
  saqState.results.forEach((r, i) => {
    const q = SAQ_QUESTIONS.find(sq => sq.id === r.id);
    if (!q) return;
    const ratingLabel = r.rating === 'got' ? '✓ Got it' : r.rating === 'partial' ? '~ Partial' : '✗ Missed';
    const ratingCls   = r.rating === 'got' ? 'rev-correct' : r.rating === 'partial' ? 'rev-partial' : 'rev-wrong';
    const marksText   = q.marks === 1 ? '1 mark' : q.marks + ' marks';
    html += `
      <div class="rev-item">
        <div class="rev-item-header">
          <span class="rev-item-num">Q${i + 1}</span>
          <span class="rev-topic">${q.topic}</span>
          <span class="rev-marks">${marksText}</span>
          <span class="${ratingCls}">${ratingLabel}</span>
        </div>
        <div class="rev-question">${q.question}</div>
        <details class="saq-rev-details">
          <summary>Model answer</summary>
          <div class="saq-model-answer">${q.answer}</div>
        </details>
      </div>`;
  });
  document.getElementById('saqRevContent').innerHTML = html || '<p style="color:var(--ink-dim)">No answers to review.</p>';
}

// SAQ inline rendering for All Random mode
function renderSaqInlineQ() {
  const total = state.questions.length;
  const i = state.currentQ;
  const item = state.questions[i];
  const q = SAQ_QUESTIONS[item.saqIdx];
  const saved = state.answers[i]; // 'got'|'partial'|'missed'|undefined
  const answered = Object.keys(state.answers).length;

  document.getElementById('qMeta').textContent = q.topic + ' · Random mode';
  const pct = (i / total) * 100;
  document.getElementById('pFill').style.width = pct + '%';
  document.getElementById('pLeft').textContent = answered + ' answered';
  document.getElementById('pRight').textContent = (i + 1) + ' / ' + total;
  document.getElementById('qCtr').textContent = 'Q' + (i + 1) + ' of ' + total;
  document.getElementById('prevBtn').disabled = i === 0;
  document.getElementById('nextBtn').style.display = i < total - 1 ? '' : 'none';
  document.getElementById('finBtn').style.display = i === total - 1 ? '' : 'none';

  const marksText = q.marks === 1 ? '1 mark' : q.marks + ' marks';

  let bodyHtml;
  if (saved) {
    const ratingLabel = saved === 'got' ? '✓ Got it' : saved === 'partial' ? '~ Partial' : '✗ Missed';
    const ratingCls   = saved === 'got' ? 'saq-rated-got' : saved === 'partial' ? 'saq-rated-partial' : 'saq-rated-missed';
    bodyHtml = `
      <div class="saq-compare-label" style="margin-top:14px">Model answer:</div>
      <div class="saq-model-answer">${q.answer}</div>
      <div class="saq-rated ${ratingCls}" style="margin-top:12px">${ratingLabel}</div>`;
  } else {
    bodyHtml = `
      <div class="saq-input-area">
        <label class="saq-input-label">Your answer:</label>
        <textarea class="saq-input" id="saqTextareaInline" placeholder="Write your answer here..." rows="4"></textarea>
      </div>
      <button class="saq-reveal-btn" id="saqRevealBtnInline" onclick="revealSaqInlineAnswer()">Reveal Answer</button>
      <div class="saq-reveal-section" id="saqRevealSectionInline" style="display:none">
        <div class="saq-compare-row">
          <div>
            <div class="saq-compare-label">Your answer:</div>
            <div class="saq-your-text" id="saqYourTextInline"></div>
          </div>
          <div>
            <div class="saq-compare-label">Model answer:</div>
            <div class="saq-model-answer" id="saqModelAnswerInline"></div>
          </div>
        </div>
        <div class="saq-rating-row">
          <div class="saq-rating-label">How did you do?</div>
          <div class="saq-rating-btns">
            <button class="saq-rating-btn missed" onclick="rateSaqInline('missed')">✗ Missed</button>
            <button class="saq-rating-btn partial" onclick="rateSaqInline('partial')">~ Partial</button>
            <button class="saq-rating-btn got" onclick="rateSaqInline('got')">✓ Got it</button>
          </div>
        </div>
      </div>`;
  }

  document.getElementById('qArea').innerHTML = `
    <div class="qcard saq-card">
      <div class="saq-header">
        <div class="lec-tag">${q.topic}</div>
        <div class="saq-marks-badge">${marksText}</div>
      </div>
      <div class="qtext">${q.question}</div>
      ${bodyHtml}
    </div>`;
}

function revealSaqInlineAnswer() {
  const item = state.questions[state.currentQ];
  const q = SAQ_QUESTIONS[item.saqIdx];
  const textarea = document.getElementById('saqTextareaInline');
  document.getElementById('saqYourTextInline').textContent = textarea.value.trim() || '(no answer written)';
  document.getElementById('saqModelAnswerInline').textContent = q.answer;
  document.getElementById('saqRevealSectionInline').style.display = '';
  document.getElementById('saqRevealBtnInline').style.display = 'none';
  document.getElementById('saqRevealSectionInline').scrollIntoView({ behavior: 'smooth', block: 'nearest' });
}

function rateSaqInline(rating) {
  state.answers[state.currentQ] = rating;
  saveResume();
  if (typeof shaderAnswerFlash === 'function') shaderAnswerFlash(rating === 'got');
  renderQ();
}

