buildHome();
syncTimerCheckboxes();


// ═══════════════════════════════════════════════════════════════
// MIDNIGHT LAB SHADER
// ═══════════════════════════════════════════════════════════════
const VERT_S = `attribute vec2 a_pos; void main(){ gl_Position = vec4(a_pos,0.0,1.0); }`;
const COMMON_S = `
precision highp float;
uniform vec2 u_res; uniform float u_time; uniform vec2 u_mouse;
uniform vec2 u_click; uniform float u_clickTime;
uniform float u_answer; uniform float u_answerTime;
uniform float u_speed; uniform vec3 u_accent;
float hash(vec2 p){ return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453); }
float noise(vec2 p){
  vec2 i=floor(p),f=fract(p);
  float a=hash(i),b=hash(i+vec2(1,0)),c=hash(i+vec2(0,1)),d=hash(i+vec2(1,1));
  vec2 u=f*f*(3.0-2.0*f);
  return mix(a,b,u.x)+(c-a)*u.y*(1.0-u.x)+(d-b)*u.x*u.y;
}
float fbm(vec2 p){float v=0.0,a=0.5;for(int i=0;i<5;i++){v+=a*noise(p);p*=2.02;a*=0.5;}return v;}
`;
const FRAG_S = COMMON_S + `
float hexDist(vec2 p){p=abs(p);float c=dot(p,normalize(vec2(1.0,1.732)));c=max(c,p.x);return c;}
vec4 hexCoords(vec2 uv){vec2 r=vec2(1.0,1.732),h=r*0.5,a=mod(uv,r)-h,b=mod(uv-h,r)-h;vec2 gv=dot(a,a)<dot(b,b)?a:b;return vec4(gv,uv-gv);}
void main(){
  vec2 uv=(gl_FragCoord.xy-0.5*u_res)/u_res.y;
  vec2 m=(u_mouse-0.5)*vec2(u_res.x/u_res.y,1.0);
  float t=u_time*0.06*u_speed;
  vec2 p=uv*1.2;
  p+=0.25*vec2(fbm(p+vec2(0.0,t)),fbm(p+vec2(3.2,-t)));
  float a1=fbm(p+t*1.2),a2=fbm(p*1.7-t*0.8+4.2);
  vec3 deep=vec3(0.020,0.028,0.055),indigo=vec3(0.08,0.12,0.32),teal=u_accent*0.85;
  vec3 col=mix(deep,indigo,smoothstep(0.2,0.9,a1));
  col=mix(col,teal*0.35,smoothstep(0.4,0.95,a2));
  col+=teal*0.15*exp(-length(uv-m)*3.5);
  vec4 h=hexCoords(uv*10.0+vec2(t*2.0,0.0));
  float edge=hexDist(h.xy);
  col+=teal*0.05*(smoothstep(0.49,0.495,edge)-smoothstep(0.495,0.50,edge));
  float dC=length(uv-(u_click-0.5)*vec2(u_res.x/u_res.y,1.0));
  col+=teal*0.25*max(0.0,sin(dC*18.0-u_clickTime*6.0)*exp(-dC*3.5)*exp(-u_clickTime*1.8));
  float aFade=exp(-u_answerTime*2.2);
  if(u_answer>0.5) col+=vec3(0.25,0.9,0.55)*0.18*aFade;
  else if(u_answer<-0.5){col+=vec3(0.9,0.25,0.35)*0.22*aFade;col*=1.0-0.08*aFade*sin(uv.y*120.0);}
  col*=1.0-0.35*dot(uv,uv);
  gl_FragColor=vec4(col,1.0);
}`;
function hexToRgb(hex){const h=hex.replace('#','');const n=parseInt(h,16);return[((n>>16)&255)/255,((n>>8)&255)/255,(n&255)/255];}

// ── Bifröst aurora shader (Midnight / Vellum themes) ────────────
const FRAG_BIFROST = `
precision highp float;
uniform vec2 u_res; uniform float u_time; uniform vec2 u_mouse;
uniform vec2 u_click; uniform float u_clickTime;
uniform float u_answer; uniform float u_answerTime;
float hash(vec2 p){ return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453); }
float vnoise(vec2 p){
  vec2 i=floor(p),f=fract(p);
  float a=hash(i),b=hash(i+vec2(1,0)),c=hash(i+vec2(0,1)),d=hash(i+vec2(1,1));
  vec2 u=f*f*(3.0-2.0*f);
  return mix(a,b,u.x)+(c-a)*u.y*(1.0-u.x)+(d-b)*u.x*u.y;
}
float fbm(vec2 p){float v=0.0,a=0.5;for(int i=0;i<6;i++){v+=a*vnoise(p);p=p*2.03+vec2(1.7,1.3);a*=0.5;}return v;}
float curtain(vec2 uv,float t,float seed){
  float wob=fbm(vec2(uv.x*2.0+seed,t*0.25));
  float band=exp(-pow((uv.y-0.15-wob*0.5)*2.6,2.0));
  band*=smoothstep(0.0,0.3,fbm(vec2(uv.x*4.0+seed*3.0,t*0.4)));
  return band;
}
void main(){
  vec2 uv=gl_FragCoord.xy/u_res.xy;
  vec2 p=(gl_FragCoord.xy-0.5*u_res)/u_res.y;
  float t=u_time*0.12;
  vec3 zenith=vec3(0.020,0.030,0.065),horizon=vec3(0.045,0.055,0.110);
  vec3 col=mix(horizon,zenith,smoothstep(0.0,1.0,uv.y));
  col*=0.85;
  vec2 sp=floor(p*240.0);float sh=hash(sp);
  float star=step(0.997,sh);float twinkle=0.5+0.5*sin(u_time*2.0+sh*30.0);
  col+=vec3(0.85,0.85,0.95)*star*twinkle*0.9;
  float c1=curtain(uv+vec2(0.0,0.02),t,0.0);
  float c2=curtain(uv+vec2(0.0,0.10),t*1.3,3.7);
  float c3=curtain(uv+vec2(0.0,-0.05),t*0.8,7.4);
  col+=vec3(0.18,0.78,0.55)*c1*0.55;
  col+=vec3(0.20,0.55,0.85)*c2*0.45;
  col+=vec3(0.78,0.35,0.55)*c3*0.30;
  float fog=fbm(p*1.5+vec2(t*0.6,0.0));
  col=mix(col,col*0.55,smoothstep(0.0,0.4,(1.0-uv.y)*fog));
  vec2 mp=(u_mouse-0.5)*vec2(u_res.x/u_res.y,1.0);
  float r=length(p-mp);
  col+=vec3(0.82,0.55,0.30)*0.10*exp(-r*4.5);
  vec2 cp=(u_click-0.5)*vec2(u_res.x/u_res.y,1.0);
  float dC=length(p-cp);
  float wave=sin(dC*22.0-u_clickTime*7.0)*exp(-dC*3.5)*exp(-u_clickTime*1.6);
  col+=vec3(0.82,0.55,0.30)*0.30*max(0.0,wave);
  float aF=exp(-u_answerTime*1.8);
  if(u_answer>0.5) col+=vec3(0.30,0.85,0.45)*0.12*aF;
  else if(u_answer<-0.5){col+=vec3(0.85,0.20,0.20)*0.18*aF;col*=1.0-0.10*aF*step(0.5,fract(p.y*100.0+u_time*8.0));}
  col*=1.0-0.45*dot(p,p);
  gl_FragColor=vec4(col,1.0);
}`;

const SS = {
  t0:performance.now(), mouse:[0.5,0.5], target:[0.5,0.5],
  click:[0.5,0.5], clickStart:-9999, answer:0, answerStart:-9999,
  speed:0.2, accent:'#7fe3d0',
  time(){return(performance.now()-this.t0)/1000;},
  clickTime(){return Math.max(0,(performance.now()-this.clickStart)/1000);},
  answerTime(){return Math.max(0,(performance.now()-this.answerStart)/1000);},
};
(function(){
  const cont=document.getElementById('shaderLayer');
  if(!cont) return;
  const cv=document.createElement('canvas');
  cv.style.cssText='position:absolute;inset:0;width:100%;height:100%;display:block;';
  cont.appendChild(cv);
  const gl=cv.getContext('webgl',{antialias:false,premultipliedAlpha:false});
  if(!gl) return;
  function mkShader(type,src){const s=gl.createShader(type);gl.shaderSource(s,src);gl.compileShader(s);return gl.getShaderParameter(s,gl.COMPILE_STATUS)?s:null;}
  const buf=gl.createBuffer();
  gl.bindBuffer(gl.ARRAY_BUFFER,buf);
  gl.bufferData(gl.ARRAY_BUFFER,new Float32Array([-1,-1,1,-1,-1,1,1,1]),gl.STATIC_DRAW);
  let currentProg=null, U={};
  function buildProgram(fragSrc){
    const vs=mkShader(gl.VERTEX_SHADER,VERT_S),fs=mkShader(gl.FRAGMENT_SHADER,fragSrc);
    if(!vs||!fs) return;
    const p=gl.createProgram();
    gl.attachShader(p,vs);gl.attachShader(p,fs);gl.linkProgram(p);
    if(!gl.getProgramParameter(p,gl.LINK_STATUS)) return;
    gl.useProgram(p);
    const ap=gl.getAttribLocation(p,'a_pos');
    gl.enableVertexAttribArray(ap);gl.vertexAttribPointer(ap,2,gl.FLOAT,false,0,0);
    currentProg=p;
    U={res:gl.getUniformLocation(p,'u_res'),time:gl.getUniformLocation(p,'u_time'),mouse:gl.getUniformLocation(p,'u_mouse'),click:gl.getUniformLocation(p,'u_click'),clickTime:gl.getUniformLocation(p,'u_clickTime'),answer:gl.getUniformLocation(p,'u_answer'),answerTime:gl.getUniformLocation(p,'u_answerTime'),speed:gl.getUniformLocation(p,'u_speed'),accent:gl.getUniformLocation(p,'u_accent')};
  }
  window.shaderInit=buildProgram;
  window.shaderSwitch=buildProgram;
  function rsz(){const d=Math.min(window.devicePixelRatio||1,2),w=Math.max(1,Math.round(cv.clientWidth*d)),h=Math.max(1,Math.round(cv.clientHeight*d));if(cv.width!==w||cv.height!==h){cv.width=w;cv.height=h;gl.viewport(0,0,w,h);}}
  new ResizeObserver(rsz).observe(cv);rsz();
  function frame(){
    if(!currentProg){requestAnimationFrame(frame);return;}
    const a=hexToRgb(SS.accent);
    gl.uniform2f(U.res,cv.width,cv.height);gl.uniform1f(U.time,SS.time());
    gl.uniform2f(U.mouse,SS.mouse[0],SS.mouse[1]);gl.uniform2f(U.click,SS.click[0],SS.click[1]);
    gl.uniform1f(U.clickTime,SS.clickTime());gl.uniform1f(U.answer,SS.answer);
    gl.uniform1f(U.answerTime,SS.answerTime());gl.uniform1f(U.speed,SS.speed);
    gl.uniform3f(U.accent,a[0],a[1],a[2]);gl.drawArrays(gl.TRIANGLE_STRIP,0,4);
    requestAnimationFrame(frame);
  }
  requestAnimationFrame(frame);
})();
window.addEventListener('pointermove',e=>{SS.target=[e.clientX/window.innerWidth,1-e.clientY/window.innerHeight];});
window.addEventListener('pointerdown',e=>{SS.click=[e.clientX/window.innerWidth,1-e.clientY/window.innerHeight];SS.clickStart=performance.now();if(!e.target.closest('.modal,.btn,select,input')){const r=document.createElement('div');r.className='ripple';r.style.left=e.clientX+'px';r.style.top=e.clientY+'px';document.body.appendChild(r);setTimeout(()=>r.remove(),900);}});
(function ease(){SS.mouse[0]+=(SS.target[0]-SS.mouse[0])*0.12;SS.mouse[1]+=(SS.target[1]-SS.mouse[1])*0.12;requestAnimationFrame(ease);})();
window.shaderAnswerFlash=function(correct){SS.answer=correct?1:-1;SS.answerStart=performance.now();setTimeout(()=>{SS.answer=0;},3200);};
// ═══════════════════════════════════════════════════════════════
// BLOCK 2 EQUATIONS — STUDY & PRACTICE
// ═══════════════════════════════════════════════════════════════

let _eqStudyRendered = false;
let _eqPracticeRendered = false;

function showEquations() {
  showScreen('equations');
  if (!_eqStudyRendered) { renderEqStudy(); _eqStudyRendered = true; }
}

function showEqTab(tab) {
  document.querySelectorAll('#eqTabs .tab').forEach(t => t.classList.remove('on'));
  document.getElementById('eqTab_' + tab).classList.add('on');
  document.getElementById('eqStudy').style.display   = tab === 'study'    ? '' : 'none';
  document.getElementById('eqPractice').style.display = tab === 'practice' ? '' : 'none';
  if (tab === 'practice' && !_eqPracticeRendered) { renderEqPractice(); _eqPracticeRendered = true; }
}

function renderEqStudy() {
  const el = document.getElementById('eqStudy');
  el.innerHTML = EQUATIONS.map((eq, i) => `
    <div class="eq-card" id="eqCard_${i}">
      <button class="eq-card-head" onclick="toggleEqCard(${i})">
        <div>
          <div class="eq-name">${eq.name}</div>
          <div class="eq-formula">${eq.formula}</div>
        </div>
        <span class="eq-chevron">▶</span>
      </button>
      <div class="eq-body">
        <div class="eq-vars">
          ${eq.variables.map(v => `<div class="eq-var-row"><span class="eq-sym">${v.sym}</span><span class="eq-desc">${v.desc}</span></div>`).join('')}
        </div>
        <p class="eq-expl">${eq.explanation}</p>
        <div class="eq-session">📖 ${eq.session}</div>
      </div>
    </div>`).join('');
}

function toggleEqCard(i) {
  const card = document.getElementById('eqCard_' + i);
  card.classList.toggle('open');
}

function renderEqPractice() {
  const b = BLOCKS['eq2'];
  const total = b.lectures['Equations Practice'].length;
  document.getElementById('eqPractice').innerHTML = `
    <div class="eq-practice-panel">
      <p class="eq-practice-desc">
        ${total} exam-style calculation questions covering all Block 2 equations.
        Values are randomised each session — you must use the equation to get the right answer.
      </p>
      <button class="btn btn-green eq-start-btn" onclick="startEqPractice()">Start Practice →</button>
    </div>`;
}

function startEqPractice() {
  const b   = BLOCKS['eq2'];
  const lec = Object.keys(b.lectures)[0];
  const pool = b.lectures[lec].map((q, idx) => ({
    lecture: lec, qIdx: idx,
    q: shuffleAnswers(resolveQuestion(q)),
    blockName: b.name
  }));
  state.blockId     = 'eq2';
  state.questions   = pool;
  state.answers     = {};
  state.currentQ    = 0;
  state.attemptId   = Date.now().toString();
  state.isRandom    = false;
  state.isAllRandom = false;
  clearResume();
  document.getElementById('qTitle').textContent = 'Block 2 Equations — Practice';
  showScreen('quiz');
  renderQ();
}

// clock
(function tick(){const el=document.getElementById('topClock');if(el)el.textContent=new Date().toLocaleTimeString(undefined,{hour:'2-digit',minute:'2-digit'});setTimeout(tick,30000);})();
// fps
let ff=0,fl=performance.now();(function fpsLoop(){ff++;const n=performance.now();if(n-fl>1000){const el=document.getElementById('railFps');if(el)el.textContent='FPS '+Math.round(ff*1000/(n-fl));ff=0;fl=n;}requestAnimationFrame(fpsLoop);})();
// theme toggle + init (must run after SS, FRAG_BIFROST, and window.shaderInit are all defined)
document.querySelector('.mode-toggle')?.addEventListener('click',e=>{const btn=e.target.closest('button[data-mode]');if(btn)applyTheme(btn.dataset.mode);});
initTheme();
